 public static string Run(){string dir="Assets/Resources/GothicArchitecture/",src="Assets/03_Models/StructuresItemsInMap/KayKit_HalloweenBits_1.0_FREE/Assets/fbx(unity)/";var atlas=AssetDatabase.LoadAssetAtPath<Texture2D>(src+"halloweenbits_texture.png");if(!atlas)throw new System.Exception("Missing cemetery atlas");foreach(string name in new[]{"BurialBench","BurialLantern","BurialCoffin","BurialTree","BurialCross","BurialGate"}){string path=dir+name+".mat";var m=AssetDatabase.LoadAssetAtPath<Material>(path);if(!m){m=new Material(Shader.Find("Universal Render Pipeline/Lit"));AssetDatabase.CreateAsset(m,path);}m.SetTexture("_BaseMap",atlas);m.SetColor("_BaseColor",new Color(.54f,.58f,.58f));m.SetFloat("_Smoothness",.18f);var g=PrefabUtility.LoadPrefabContents(dir+name+".prefab");try{foreach(var r in g.GetComponentsInChildren<Renderer>())r.sharedMaterials=Enumerable.Repeat(m,r.sharedMaterials.Length).ToArray();PrefabUtility.SaveAsPrefabAsset(g,dir+name+".prefab");}finally{PrefabUtility.UnloadPrefabContents(g);}EditorUtility.SetDirty(m);}AssetDatabase.SaveAssets();return "Original wood, iron and burial atlas restored on six new modules";}
